CREATE TABLE IF NOT EXISTS branches(id CHAR(36) PRIMARY KEY,name VARCHAR(150) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',accepts_reservations BOOLEAN NOT NULL DEFAULT TRUE);
