CREATE TABLE IF NOT EXISTS table_payment_acks(payment_id CHAR(36) PRIMARY KEY,table_id CHAR(36) NOT NULL,order_id CHAR(36) NOT NULL,branch_id CHAR(36) NOT NULL,ack JSON NOT NULL);
CREATE TABLE IF NOT EXISTS reservation_order_claims(reservation_id CHAR(36) NOT NULL,order_id CHAR(36) NOT NULL PRIMARY KEY,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
